"""Local web UI for viewing and refreshing reports."""
from __future__ import annotations
import json
from datetime import datetime
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
from urllib.parse import urlparse
from .cli import run
from .core import CN

ROOT = Path(__file__).resolve().parents[1]
REPORTS = ROOT / "reports"
PAGE = r"""<!doctype html><html lang='zh-CN'><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Tripo AI 舆情日报</title><style>
:root{--ink:#172033;--muted:#667085;--navy:#173b72;--blue:#2563eb;--purple:#7c3aed;--cyan:#0891b2;--gold:#d97706;--line:#dbe4f0}*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI","PingFang SC","Microsoft YaHei",sans-serif;color:var(--ink);background:linear-gradient(180deg,#eef3fb 0,#f7f9fc 280px)}.shell{max-width:1320px;margin:auto;padding:26px}.hero{padding:29px 34px;border-radius:20px;color:white;background:linear-gradient(118deg,#123b7a,#6139a9 58%,#087f8c);box-shadow:0 16px 38px #1e3a5f30}.titlebar{display:flex;align-items:center;justify-content:space-between;gap:20px;flex-wrap:wrap}.hero h1{margin:0;font-size:32px;letter-spacing:.02em}.tabs{display:flex;gap:8px;padding:5px;background:#071c4b35;border:1px solid #ffffff24;border-radius:13px}.tab{display:inline-block;padding:9px 15px;border-radius:9px;color:#edf4ff;text-decoration:none;font-weight:750;font-size:14px}.tab.active{background:white;color:#174ea6;box-shadow:0 3px 10px #142c5d30}.hero p{margin:10px 0 0;color:#e8efff;font-size:15px}.toolbar{display:flex;align-items:center;gap:10px;flex-wrap:wrap;margin-top:22px}.btn{border:0;border-radius:9px;padding:10px 15px;font-weight:700;cursor:pointer}.primary{background:white;color:#174ea6}.secondary{background:#ffffff20;color:white;border:1px solid #ffffff2e}.grid{display:grid;grid-template-columns:250px minmax(0,1fr);gap:22px;margin-top:22px}.panel,.report{background:white;border:1px solid var(--line);border-radius:18px;box-shadow:0 8px 24px #33415510}.panel{padding:19px;height:max-content;position:sticky;top:18px}.panel h2{margin:0 0 12px;font-size:16px;color:#24324a}.source{padding:12px;border-radius:10px;background:#eaf2ff;margin:9px 0;font-size:12px;line-height:1.6;border:1px solid #d7e6fb}.source:nth-of-type(2){background:#f4edff;border-color:#e5d8fb}.source:nth-of-type(3){background:#e8f8f5;border-color:#ccece6}.source b{display:block;color:#174ea6;font-size:14px;margin-bottom:3px}.history button{width:100%;text-align:left;background:#f4efff;color:#4c1d95;margin:5px 0;font-size:12px}.report{padding:34px 42px;min-height:650px}.report .daily-report>h1{font-size:28px;line-height:1.4;color:#143c72;border-bottom:1px solid #ccdaec;padding:0 0 18px;margin:0 0 18px}.report .daily-report>p{display:inline-block;margin:4px 8px 4px 0;padding:6px 10px;border-radius:8px;background:#f2f6fb;color:#526176}.report h2{font-size:21px;color:white;background:linear-gradient(100deg,#5f36aa,#8154c8);border-left:0;padding:13px 17px;margin:38px 0 18px;border-radius:11px;box-shadow:0 5px 14px #6b3db326}.report h2:nth-of-type(2n){background:linear-gradient(100deg,#087785,#10a3b6);box-shadow:0 5px 14px #078b9825}.report h2:first-of-type{background:linear-gradient(100deg,#174b87,#3779c5)}.report h3{font-size:18px;line-height:1.45;color:#164a85;background:#eaf3ff;border:1px solid #cfe1f8;padding:12px 15px;border-radius:10px;margin:23px 0 12px}.report h4{font-size:16px;line-height:1.5;color:#54308d;background:#f7f2ff;border:1px solid #e6d8fa;border-left:5px solid #8b5cf6;padding:12px 14px;border-radius:9px;margin:18px 0 9px}.report p{font-size:14px;line-height:1.78;color:#536176;margin:8px 0}.report a{color:#175cd3;text-decoration:none;font-weight:680}.report a:hover{text-decoration:underline}.report ul{margin:9px 0 22px;padding:0;list-style:none}.report li{font-size:14px;line-height:1.75;padding:10px 14px;margin:7px 0;background:#f8fafc;border:1px solid #e6ebf2;border-left:4px solid #9eb8dc;border-radius:8px;color:#37465c}.report li .field{display:inline-block;color:#5f36aa;font-weight:800;margin-right:6px}.report li.summary-cn{background:#fff8e8;border-color:#f7dfad;border-left-color:#e9a20b;color:#543b0e}.report li.summary-en{background:#ebf9f7;border-color:#ccece6;border-left-color:#169d8e;color:#24534f}.report li.impact{background:#f1edff;border-color:#dfd5fc;border-left-color:#7353d2}.report li:nth-last-child(2){background:#fff5ed;border-left-color:#ed7a2b}.meta{display:flex;gap:10px;flex-wrap:wrap;color:#e5edff;font-size:13px}.badge{display:inline-block;padding:5px 10px;border-radius:999px;background:#dcfce7;color:#166534}.empty{padding:50px;text-align:center;color:var(--muted)}@media(max-width:800px){.shell{padding:12px}.grid{grid-template-columns:1fr}.panel{position:static}.report{padding:22px 18px}.hero{padding:23px 20px}.hero h1{font-size:24px}.tabs{width:100%}.tab{flex:1;text-align:center;padding:8px}.report .daily-report>h1{font-size:22px}.report h2{font-size:18px;margin-top:28px}.report h3{font-size:17px}.report h4{font-size:15px}}</style><body><div class='shell'><section class='hero'><div class='titlebar'><h1>Tripo AI 舆情与行业日报</h1><nav class='tabs'><a class='tab' id='daily-tab' href='/'>舆情与行业日报</a><a class='tab' id='media-tab' href='/priority'>重点关注媒体</a></nav></div><p id='subtitle'>面向 VAST / Tripo AI 的 AI 3D、竞品、出海、融资与行业政策情报中心</p><div class='toolbar'><button class='btn primary' id='b' onclick='refresh()'>刷新日报</button><button class='btn secondary' onclick='load()'>重新加载</button><button class='btn secondary' onclick="location.href='/api/export.xlsx'">导出当日 Excel</button><span id='s' class='meta'>正在读取...</span></div></section><div class='grid'><aside class='panel'><h2>来源概览</h2><div class='source'><b id='source-count'>已配置 28 个公开来源</b><span id='source-detail'>正在检查本次可用来源…</span></div><div class='source'><b>覆盖方向</b>AI 3D · 竞品 · 中国公司出海 · VC 融资 · 政策 · 芯片</div><div class='source'><b>数据原则</b>原始链接、时间窗口、失败来源透明标记</div><h2 style='margin-top:25px'>历史日报</h2><div id='history' class='history'></div></aside><main class='report' id='report'><div class='empty'>正在加载日报...</div></main></div></div><script>
const KEY='tripo-report-history-v1',MEDIA=location.pathname==='/priority';document.getElementById(MEDIA?'media-tab':'daily-tab').classList.add('active');if(MEDIA)document.getElementById('subtitle').textContent='TechCrunch、The Information、Forbes、Wired、The Verge 与 MIT Technology Review 当日公开报道';function esc(s){return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]))}function decorate(root){root.querySelectorAll('li').forEach(li=>{let t=li.textContent||'';let m=t.match(/^([^：]{2,24}：)/);if(m){let html=li.innerHTML;li.innerHTML=`<span class="field">${esc(m[1])}</span>`+html.slice(m[1].length)}if(t.startsWith('中文报道概述：'))li.classList.add('summary-cn');if(t.startsWith('English summary:'))li.classList.add('summary-en');if(t.startsWith('对 Tripo/VAST 的影响'))li.classList.add('impact');if(t.startsWith('话题数据：')){li.style.background='#eaf2ff';li.style.borderLeftColor='#3478d4'}})}function save(day,html){let a=JSON.parse(localStorage.getItem(KEY)||'[]').filter(x=>x.day!==day);a.unshift({day,html,time:new Date().toLocaleString()});localStorage.setItem(KEY,JSON.stringify(a.slice(0,30)));drawHistory()}function drawHistory(){let a=JSON.parse(localStorage.getItem(KEY)||'[]');history.innerHTML=a.length?a.map((x,i)=>`<button class='btn' onclick='showHistory(${i})'>${esc(x.day)}<small style='display:block;color:#64748b'>${esc(x.time)}</small></button>`).join(''):'<div style="color:#94a3b8;font-size:13px">刷新后自动保存历史</div>'}function showHistory(i){let a=JSON.parse(localStorage.getItem(KEY)||'[]');if(a[i]){report.innerHTML=a[i].html;decorate(report)}s.textContent='已查看历史日报：'+a[i].day}async function load(){try{let d=await (await fetch('/api/status')).json();s.innerHTML=`<span class='badge'>${esc(d.message)}</span>`;if(d.sources){document.getElementById('source-count').textContent=`已配置 ${d.sources.configured} 个公开来源`;document.getElementById('source-detail').textContent=`本次成功 ${d.sources.ok} 个，失败 ${d.sources.failed} 个`}let endpoint=MEDIA?'/api/priority':'/api/report';let h=await (await fetch(endpoint+'?t='+Date.now(),{cache:'no-store'})).text();report.innerHTML=h;decorate(report);save(d.message.replace('最新日报：',''),h)}catch(e){s.textContent='加载失败：'+e}}async function refresh(){b.disabled=true;b.textContent='采集中...';s.textContent='正在访问公开来源并生成日报';try{let d=await (await fetch('/api/refresh',{method:'POST'})).json();if(!d.html)throw new Error(d.message||'生成失败');s.textContent=d.message;let h=MEDIA?await (await fetch('/api/priority?t='+Date.now(),{cache:'no-store'})).text():d.html;report.innerHTML=h;decorate(report);if(d.sources){document.getElementById('source-count').textContent=`已配置 ${d.sources.configured} 个公开来源`;document.getElementById('source-detail').textContent=`本次成功 ${d.sources.ok} 个，失败 ${d.sources.failed} 个`}save(d.day,d.html)}catch(e){s.textContent='刷新失败：'+e}finally{b.disabled=false;b.textContent='刷新日报'}}drawHistory();load();</script></body></html>"""
def latest():
    x=sorted(REPORTS.glob('*.html'),reverse=True); return x[0] if x else None
class Handler(BaseHTTPRequestHandler):
    def log_message(self,*a): pass
    def out(self,obj,code=200):
        b=json.dumps(obj,ensure_ascii=False).encode(); self.send_response(code); self.send_header('Content-Type','application/json; charset=utf-8'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b)
    def do_GET(self):
        p=urlparse(self.path).path
        if p in ('/','/priority'):
            b=PAGE.encode(); self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b); return
        if p=='/api/status':
            f=latest(); self.out({'url':'/reports/'+f.name if f else None,'message':f'最新日报：{f.stem}' if f else '暂无日报，请点击刷新'}); return
        if p.startswith('/reports/'):
            f=REPORTS/Path(p.removeprefix('/reports/')).name
            if f.exists() and f.suffix=='.html':
                b=f.read_bytes(); self.send_response(200); self.send_header('Content-Type','text/html; charset=utf-8'); self.send_header('Content-Length',str(len(b))); self.end_headers(); self.wfile.write(b); return
        self.send_error(404)
    def do_POST(self):
        if urlparse(self.path).path!='/api/refresh': self.send_error(404); return
        day=datetime.now(CN).date().isoformat(); rc=run(day); self.out({'ok':rc==0,'message':'刷新完成' if rc==0 else '刷新完成，但部分来源失败；请查看日报顶部状态'})
def main():
    import argparse, os
    p=argparse.ArgumentParser(); p.add_argument('--host',default=os.getenv('HOST','127.0.0.1')); p.add_argument('--port',type=int,default=int(os.getenv('PORT','8765'))); a=p.parse_args(); print(f'网页地址：http://{a.host}:{a.port}'); ThreadingHTTPServer((a.host,a.port),Handler).serve_forever()
if __name__=='__main__': main()
